CREATE OR REPLACE FUNCTION public.rpc_admin_set_user_role(p_user_id text, p_role text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, private, pg_temp AS $$ DECLARE v_actor text := private.current_app_user_id(); v_role text := private.current_app_user_role(); v_user public.users%ROWTYPE; v_count integer; BEGIN IF auth.uid() IS NULL OR v_actor IS NULL OR v_role NOT IN ('admin','owner') THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='ADMIN_REQUIRED'; END IF; IF p_role IS NULL OR p_role NOT IN ('user','client','lawyer','admin') THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='INVALID_ROLE'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended('public.rpc_admin_set_user_role',0)); SELECT * INTO v_user FROM public.users WHERE id=p_user_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002', MESSAGE='USER_NOT_FOUND'; END IF; IF v_role <> 'owner' AND (v_user.role IN ('admin','owner') OR p_role='admin') THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='OWNER_REQUIRED'; END IF; IF v_user.role='owner' AND p_role<>'owner' THEN SELECT count(*) INTO v_count FROM public.users WHERE role='owner'; IF v_count<=1 THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='CANNOT_DEMOTE_LAST_OWNER'; END IF; END IF; IF v_user.role='admin' AND p_role<>'admin' THEN SELECT count(*) INTO v_count FROM public.users WHERE role='admin'; IF v_count<=1 THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='CANNOT_DEMOTE_LAST_ADMIN'; END IF; END IF; UPDATE public.users SET role=p_role,updated_at=now() WHERE id=p_user_id RETURNING * INTO v_user; RETURN to_jsonb(v_user); END; $$; REVOKE ALL ON FUNCTION public.rpc_admin_set_user_role(text,text) FROM PUBLIC, anon, service_role; GRANT EXECUTE ON FUNCTION public.rpc_admin_set_user_role(text,text) TO authenticated;